      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Previous blood tests"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reported as normal approximately 3 months before this follow-up: FBC, U&E, LFT, CRP, TSH, and coeliac testing."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Previous stool tests"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Stool M/C/S and O/C reported as normal approximately 3 months before this follow-up, per EMR."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Previous faecal calprotectin"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reported as normal approximately 3 months before this follow-up, per EMR."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Cardiovascular and respiratory examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Heart sounds dual, no murmur, JVP not raised, chest clear."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Abdominal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild distension only; abdomen soft and non-tender, no guarding or rebound, no masses or hepatosplenomegaly, bowel sounds normal, and no shifting dullness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Peripheral examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No pitting oedema; legs symmetrical; rings not tight on examination."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Skin examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No urticaria or angioedema."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-17",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Pain associated with bowel symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Pain described as minimal."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-18",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "School stress"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Increased school stress briefly noted; clinician considered it likely contributing."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Loperamide"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "2 mg after a loose stool as needed; maximum 8 mg per day",
            "asNeededBoolean": true,
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 2,
                  "unit": "mg"
                }
              }
            ],
            "maxDosePerPeriod": {
              "numerator": {
                "value": 8,
                "unit": "mg"
              },
              "denominator": {
                "value": 1,
                "unit": "day"
              }
            }
          }
        ],
        "note": [
          {
            "text": "Loperamide PRN is recorded in the EMR; patient had poor recall of the medicine. Plan was to continue PRN and the dose was clarified."
          }
        ]
      }
    }
  ]
}

